#include <iostream>

// Conceptual preview of a class architecture: blueprint vs instance
class SystemBanner {
public:
    void display() const {
        std::cout << "System ready for GradeBook processing.\n";
    }
};

int main() {
    // Creating an instance of the user-defined type
    SystemBanner banner;
    banner.display();
    return 0;
}

#include <iostream>

// GradeBook class definition
class GradeBook {
public:
    // Function that displays a welcome message to the GradeBook user
    void displayMessage() const {
        std::cout << "Welcome to the Grade Book!" << std::endl;
    } // end function displayMessage
}; // end class GradeBook - Note the mandatory semicolon!

int main() {
    GradeBook myGradeBook; // Instantiate an object of class GradeBook
    myGradeBook.displayMessage(); // Invoke member function
    return 0;
} // end main

#include <iostream>

class GradeBook {
public:
    // const member function: guarantees no mutation of object attributes
    void displayMessage() const {
        std::cout << "Welcome to the Grade Book!" << std::endl;
    }
};

int main() {
    // 1. Instantiate user-defined type GradeBook
    GradeBook book1;
    GradeBook book2;

    // 2. Invoke member function on distinct instances using dot operator
    book1.displayMessage();
    book2.displayMessage();

    return 0;
}
